import { LikeButton, Card } from "march/ui"
import { star } from "march/icons"

// favori yıldızı: kalp yerine yıldız, altın renk, tek renkli parçacıklar
export function StarRating() {
  let $on = false
  let $n = 41
  return <Card m:theme="night">
    <LikeButton liked={$on} count={$n} onToggle={(v: boolean) => { $on = v; $n += v ? 1 : -1 }}
      icon={star} m:color="brand-gold" colors="single" size="lg" label="Favorilere ekle" />
  </Card>
}

import { LikeButton } from "march/ui"

// fotoğraf beğenileri: üç fotoğraf, her birinin kendi sayacı; toplam altta
const photos = [{ name: "Gün batımı", n: 120 }, { name: "Deniz", n: 87 }, { name: "Orman", n: 9 }]

export function PhotoLikes() {
  let $liked: string[] = []
  const total = () => photos.reduce((s, p) => s + p.n, 0) + $liked.length
  return <div sx={{ flex: "col", gap: 2 }}>
    {photos.map((p) => <div sx={{ flex: ["row", "center", "between"] }}>
      <span>{p.name}</span>
      <LikeButton liked={$liked.includes(p.name)} count={p.n + ($liked.includes(p.name) ? 1 : 0)} size="sm" label={`${p.name}: beğen`}
        onToggle={(v: boolean) => $liked = v ? [...$liked, p.name] : $liked.filter((x) => x !== p.name)} />
    </div>)}
    <span sx={{ text: "sm", color: "muted" }}>Toplam {total()} beğeni</span>
  </div>
}

import { LikeButton } from "march/ui"
import { star } from "march/icons"

// LikeButton'ın özellikleri: liked, onToggle, count, size, burst, colors, label, icon (öğe ya da işlev), pop,
// burstOptions, countFormat, class
export function LikeButtonLab() {
  let $on = false
  let $n = 1999
  return <div sx={{ flex: "col", gap: 2 }}>
    <LikeButton class="lab-like" liked={$on} count={$n} countFormat="compact" onToggle={(v: boolean) => { $on = v; $n += v ? 1 : -1 }}
      label="Beğen" pop={false} burst={false} burstOptions={{ ring: false }} />
    <LikeButton class="lab-own" liked={true} onToggle={() => {}} size="sm" colors="single" icon={(on: boolean) => <span>{on ? "★" : "☆"}</span>} />
    <span class="lab-n">{$n}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { LikeButtonLab } from "./LikeButtonLab.tsx"

// LikeButtonLab'in testleri: kaydedince Testler sekmesinde çalışır
test("basınca beğenilir ve sayaç artar", async () => {
  const s = renderTest(() => <LikeButtonLab />)
  const b = s.get(".lab-like")!
  expect(b.getAttribute("aria-pressed")).toBe("false")
  await s.click(b)
  expect(s.get(".lab-like")?.getAttribute("aria-pressed")).toBe("true")
  expect(s.get(".lab-n")?.textContent).toBe("2000")
})

test("işlev ikonu duruma göre çizer", () => {
  const s = renderTest(() => <LikeButtonLab />)
  expect(s.get(".lab-own")?.textContent).toContain("★")
})
